 *
 * @param {string} str The input string to be capitalized.
 * @returns {string} The string with the first letter of each word capitalized.
 */
function capitalizeWords(str: string): string {
  if (!str) {
    return "";
  }

  // 1. Convert the entire string to lowercase to handle mixed-case input consistently.
  const lowerCaseStr = str.toLowerCase();

  // 2. Split the string into an array of words using spaces as the delimiter.
  const wordsArray: string[] = lowerCaseStr.split(' ');

  // 3. Map over the array, capitalizing the first letter of each word.
  const capitalizedWordsArray: string[] = wordsArray.map((word: string) => {
    if (word.length === 0) {
      return "";
    }
    // Take the first character, convert it to uppercase, and concatenate it with the rest of the word (from index 1 onwards).
    const firstLetter = word.charAt(0).toUpperCase();
    const restOfWord = word.slice(1);
    return `${firstLetter}${restOfWord}`;
  });

  // 4. Join the array back into a single string with spaces between words.
  return capitalizedWordsArray.join(' ');
}

