Here is a JavaScript function that sorts an array of objects by a specified key.

This function uses the built-in `Array.prototype.sort()` method and provides an example demonstrating its usage.

```javascript
/**
 * Sorts an array of objects based on the value of a specified key.
:param {Array<Object>} arr The array of objects to be sorted.
:param {string} key The key in the objects to sort by.
:param {string} [order='asc'] The sorting order: 'asc' for ascending, 'desc' for descending. Defaults to 'asc'.
:returns {Array<Object>} The sorted array of objects.
 */
function sortArrayOfObjectsByKey(arr, key, order = 'asc') {
    // Create a copy of the array to avoid mutating the original array
    const sortedArr = [...arr];

    sortedArr.sort((a, b) => {
        const valA = a[key];
        const valB = b[key];

        // Handle string comparison (case-insensitive)
        if (typeof valA === 'string' && typeof valB === 'string') {
            const comparison = valA.localeCompare(valB);
            return order === 'asc' ? comparison : -comparison;
        }

        // Handle numeric comparison
        if (typeof valA === 'number' && typeof valB === 'number') {
            return order === 'asc' ? valA - valB : valB - valA;
        }

        // Default comparison for other types (treat as strings for simplicity)
        if (valA < valB) {
            return order === 'asc' ? -1 : 1;
        }
        if (valA > valB) {
            return order === 'asc' ? 1 : -1;
        }
        return 0;
    });

    return sortedArr;
}

// --- Example Usage ---

