```javascript
/**
 * Creates a throttled version of a function that only invokes it at most once per every wait milliseconds.
 *
 * @param {Function} func The function to throttle.
 * @param {number} wait The number of milliseconds to wait between invocations.
 * @returns {Function} A new function that is the throttled version of the original.
 */
function throttle(func, wait) {
    let timeoutId = null;
    let lastArgs = null;
    let lastThis = null;
    let lastExecTime = 0;

    /**
     * The throttled function wrapper.
     * @param {...any} args Arguments passed to the throttled function.
     * @param {object} context The 'this' context for the function call.
     */
    return function(...args) {
        const context = this;
        const now = Date.now();

        // Check if we are within the cooldown period
        if (now - lastExecTime < wait) {
            // If not, store the latest arguments and context, in case we execute later
            lastArgs = args;
            lastThis = context;
            // If a timeout isn't already scheduled, schedule it to run the function
            if (!timeoutId) {
                timeoutId = setTimeout(() => {
                    // Execute the function with the last recorded arguments and context
                    func.apply(lastThis, lastArgs);
                    // Reset the state after execution
                    lastExecTime = Date.now();
                    lastArgs = null;
                    lastThis = null;
                    timeoutId = null;
                }, wait - (now - lastExecTime)); // Calculate remaining time for better accuracy
            }
