function areBracketsBalanced(s: string): boolean {
    let stack: string[] = [];

    // Define the mapping for closing brackets to their corresponding opening brackets
    const bracketMap: { [key: string]: string } = {
        ')': '(',
        ']': '[',
        '}': '{'
    };

    // Define the set of opening brackets for quick lookup
    const openingBrackets: Set<string> = new Set(['(', '[', '{']);

    for (const char of s) {
        // If the character is an opening bracket, push it onto the stack
        if (openingBrackets.has(char)) {
            stack.push(char);
        } 
        // If the character is a closing bracket
        else if (bracketMap[char]) {
            // If the stack is empty, it means we have a closing bracket without a corresponding opener
            if (stack.length === 0) {
                return false;
            }

            // Pop the top element from the stack
            const lastOpenBracket = stack.pop();

            // Check if the popped bracket matches the expected opening bracket for the current closing bracket
            if (lastOpenBracket !== bracketMap[char]) {
                return false;
            }
        }
        // Ignore any other characters
    }

    // After iterating through the entire string, the stack must be empty for the brackets to be balanced.
    return stack.length === 0;
