        return -1; // Return a sentinel value to indicate an error
    }
    if (n == 0 || n == 1) {
        return 1;
    }

    // Iteratively calculate the factorial
    long long result = 1;
    for (int i = 2; i <= n; i++) {
        result *= i;
    }

    return result;
}

