/**
 * @brief Checks if a given integer is a prime number.
 *
 * A prime number is a natural number greater than 1 that has no positive
 * divisors other than 1 and itself.
 *
 * @param n The integer to check.
 * @return true if n is a prime number, false otherwise.
 */
bool is_prime(int n) {
    // 1. Handle base cases: Numbers less than or equal to 1 are not prime.
    if (n <= 1) {
        return false;
    }

    // 2. Handle the only even prime number: 2.
    if (n == 2) {
        return true;
    }

    // 3. Handle all other even numbers (which are not prime).
    if (n % 2 == 0) {
        return false;
    }

    // 4. Check for divisibility by odd numbers up to the square root of n.
    // If n has a divisor greater than sqrt(n), it must also have a divisor
    // smaller than sqrt(n).
    int limit = (int)sqrt(n);

    for (int i = 3; i <= limit; i += 2) {
        if (n % i == 0) {
            return false; // Found a divisor, so it's not prime
        }
    }

    // If no divisors were found, the number is prime.
    return true;
}

