To make this work, we first need a definition for the structure of a node in the linked list.

```c
#include <stdio.h>
#include <stdlib.h>

// Define the structure for a node in the linked list
typedef struct Node {
    int data;
    struct Node* next;
} Node;

/**
 * @brief Computes the length (number of nodes) of a linked list.
 * 
 * @param head A pointer to the first node of the linked list.
 * @return int The total number of nodes in the list. Returns 0 if the list is empty (head is NULL).
 */
int get_list_length(Node* head) {
    int count = 0;
    Node* current = head;

    // Traverse the list from the head until the end (current becomes NULL)
    while (current != NULL) {
        count++;
        current = current->next;
    }

    return count;
}

// --- Example Usage ---

// Helper function to create a new node
Node* create_node(int data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Helper function to print the list (for verification)
void print_list(Node* head) {
    Node* current = head;
    printf("List: ");
    while (current != NULL) {
        printf("%d -> ", current->data);
        current = current->next;
    }
    printf("NULL\n");
}

// Main function to demonstrate the usage
int main() {
    // Case 1: Empty list
    Node* head1 = NULL;
    printf("Length of the empty list: %d\n", get_list_length(head1)); // Expected: 0

    // Case 2: List with multiple nodes (10 -> 20 -> 30 -> 40)
    Node* head2 = create_node(10);
    head2->next = create_node(20);
    head2->next->next = create_node(30);
    head2->next->next->next = create_node(40);

