```c
#include <stdio.h>
#include <stdbool.h>

/**
 * @brief Sorts an integer array using the bubble sort algorithm.
 *
 * @param arr The integer array to be sorted.
 * @param n The number of elements in the array.
 */
void bubbleSort(int arr[], int n) {
    // Outer loop for passes
    for (int i = 0; i < n - 1; i++) {
        // Inner loop for comparisons and swaps
        for (int j = 0; j < n - i - 1; j++) {
            // Compare adjacent elements
            if (arr[j] > arr[j + 1]) {
                // Swap arr[j] and arr[j+1]
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

/**
 * @brief Prints the elements of an integer array.
 *
 * @param arr The integer array to print.
 * @param size The number of elements in the array.
 */
void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

/**
 * @brief Main function to demonstrate the bubbleSort function.
 */
int main() {
    int data[] = {64, 34, 25, 12, 22, 11, 90};
    int n = sizeof(data) / sizeof(data[0]);

    printf("Original array: \n");
    printArray(data, n);

    // Call the sorting function
    bubbleSort(data, n);

    printf("\nSorted array (using Bubble Sort): \n");
    printArray(data, n);

    return 0;
}
```

