///
/// The check is case-insensitive and ignores non-alphanumeric characters.
///
/// # Arguments
///
/// * `s` - The string slice to check.
///
/// # Returns
///
/// `true` if the string is a palindrome, `false` otherwise.
fn is_palindrome(s: &str) -> bool {
    // 1. Filter and normalize the string:
    // Iterate over the characters, keep only alphanumeric ones, and convert them to lowercase.
    let cleaned_chars: Vec<char> = s
        .chars()
        .filter(|c| c.is_alphanumeric())
        .map(|c| c.to_ascii_lowercase())
        .collect();

    // 2. Check for palindrome property:
    // Use two pointers (or iterators) to compare the first half with the reversed second half.
    let len = cleaned_chars.len();
    if len == 0 {
        // An empty string or a string with no alphanumeric characters is considered a palindrome.
        return true;
    }

    for i in 0..(len / 2) {
        if cleaned_chars[i] != cleaned_chars[len - 1 - i] {
            return false;
        }
    }

    true
}

