#[derive(Debug, Clone, Copy)]
pub struct Point {
    /// The x-coordinate of the point.
    x: f64,
    /// The y-coordinate of the point.
    y: f64,
}

/// A utility struct or trait to handle geometric operations on points.
pub struct Geometry;

impl Geometry {
    /// Calculates the Euclidean distance between two points.
    ///
    /// The distance is calculated using the formula: sqrt((x2 - x1)^2 + (y2 - y1)^2).
    ///
    /// # Arguments
    ///
    /// * `p1` - The first point.
    /// * `p2` - The second point.
    ///
    /// # Returns
    ///
    /// The distance between `p1` and `p2` as an `f64`.
    pub fn distance(p1: &Point, p2: &Point) -> f64 {
        let dx = p2.x - p1.x;
        let dy = p2.y - p1.y;
        (dx * dx + dy * dy).sqrt()
    }
}

// --- Example Usage ---
fn main() {
    // Create two points
    let point1 = Point { x: 1.0, y: 2.0 };
    let point2 = Point { x: 4.0, y: 6.0 };

    println!("Point 1: {:?}", point1);
    println!("Point 2: {:?}", point2);

    // Calculate the distance using the Geometry utility
    let dist = Geometry::distance(&point1, &point2);

    println!("The distance between Point 1 and Point 2 is: {:.2}", dist);

    // Another example
    let point3 = Point { x: -1.0, y: 0.0 };
    let point4 = Point { x: 1.0, y: 0.0 };
    let dist2 = Geometry::distance(&point3, &point4);
    println!("The distance between Point 3 and Point 4 is: {:.2}", dist2);
}
```

