/// Finds the largest element in a slice of i32.
///
/// Returns `None` if the slice is empty.
fn find_largest(data: &[i32]) -> Option<i32> {
    if data.is_empty() {
        return None;
    }

    let mut largest = data[0];

    // Iterate over the slice starting from the second element
    for &element in data.iter().skip(1) {
        if element > largest {
            largest = element;
        }
    }

    Some(largest)
}

fn main() {
    // Test case 1: Normal case
    let numbers1 = [3, 1, 9, 4, 7, 2];
    match find_largest(&numbers1) {
        Some(max) => println!("The largest element in {:?} is: {}", numbers1, max),
        None => println!("The slice is empty."),
    }

    // Test case 2: Empty slice
