/// Reverses the elements of a mutable vector in place.
///
/// # Arguments
///
/// # `vec` - A mutable reference to the vector to be reversed.
pub fn reverse_vec<T>(vec: &mut Vec<T>) {
    let len = vec.len();
    if len == 0 {
        return;
    }

    // Iterate only up to the middle of the vector.
    // We use `i` from 0 up to (but not including) len / 2.
    for i in 0..len / 2 {
        // Calculate the index of the element to swap with.
        // If the vector has length 5, i=0 swaps with index 4, i=1 swaps with index 3.
        // (len - 1 - i) gives the corresponding element from the end.
        let j = len - 1 - i;

        // Swap the elements at indices i and j.
        vec.swap(i, j);
    }
}

// Example usage:
fn main() {
    // Example with integers
    let mut numbers = vec![1, 2, 3, 4, 5];
    println!("Original numbers: {:?}", numbers);

    reverse_vec(&mut numbers);
    println!("Reversed numbers: {:?}", numbers); // Output: [5, 4, 3, 2, 1]

    // Example with strings
    let mut words = vec!["hello", "world", "rust"];
    println!("\nOriginal words: {:?}", words);

    reverse_vec(&mut words);
    println!("Reversed words: {:?}", words); // Output: ["rust", "world", "hello"]

    // Example with an empty vector
    let mut empty_vec: Vec<i32> = vec![];
    reverse_vec(&mut empty_vec);
    println!("\nReversed empty vector: {:?}", empty_vec); // Output: []
}
```

